        "author": null,
        "siteName": "eth.limo",
        "category": "article",
        "language": null,
        "readingTime": "4 mins",
        "readingMinutes": 4,
        "wordCount": 811,
        "publishedDate": "2025-03-28",
        "savedDate": "2026-09-15T14:41:49.824000+00:00",
        "imageUrl": "http://vitalik.ca/images/icon.png",
        "sourceUrl": "https://vitalik.eth.limo/general/2025/03/29/treering.html",
